import sys

def sieve(limit):
    """返回长度为 limit+1 的列表 is_prime，is_prime[x] 为 True 表示 x 是素数"""
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return is_prime

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        # 按大小合并，保持平衡
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        self.size[rx] += self.size[ry]

def kruskal(nodes, a, is_prime):
    """对连通分量内的节点 nodes 求最小生成树总权值"""
    m = len(nodes)
    edges = []
    # 枚举分量内所有点对
    for i in range(m):
        for j in range(i + 1, m):
            u, v = nodes[i], nodes[j]
            s = a[u] + a[v]
            if is_prime[s]:
                edges.append((s, i, j))
    edges.sort(key=lambda x: x[0])
    uf = UnionFind(m)
    total = 0
    edges_used = 0
    for w, i, j in edges:
        if uf.find(i) != uf.find(j):
            uf.union(i, j)
            total += w
            edges_used += 1
            if edges_used == m - 1:
                break
    return total

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    max_sum = max(a) * 2 if a else 0
    limit = max(2000000, max_sum)  # 保证至少覆盖 2e6
    is_prime = sieve(limit)

    uf = UnionFind(n)
    # 建图，合并连通分量
    for i in range(n):
        for j in range(i + 1, n):
            if is_prime[a[i] + a[j]]:
                uf.union(i, j)

    # 统计连通分量大小
    comp_size = {}
    for i in range(n):
        root = uf.find(i)
        comp_size[root] = uf.size[root]  # 已经通过 union 维护 size，也可以用 comp_size[root]=uf.size[root]
    if not comp_size:
        print(0)
        return
    max_size = max(comp_size.values())

    # 找出所有大小为 max_size 的连通分量的根
    roots = [r for r, sz in comp_size.items() if sz == max_size]

    ans = float('inf')
    for root in roots:
        # 提取该分量内的所有节点
        nodes = [i for i in range(n) if uf.find(i) == root]
        mst_weight = kruskal(nodes, a, is_prime)
        if mst_weight < ans:
            ans = mst_weight
    print(ans)

if __name__ == "__main__":
    main()
```

### Java

```java
import java.util.*;

public class Main {
    static final int MAX_VAL = 2000000;
    static boolean[] isPrime;

    // 素数筛
    static void sieve(int limit) {
        isPrime = new boolean[limit + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;
        for (int i = 2; i * i <= limit; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= limit; j += i) {
                    isPrime[j] = false;
                }
            }
        }
    }

    // 并查集
    static class UnionFind {
        int[] parent, size;
        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }
        void union(int x, int y) {
            int rx = find(x), ry = find(y);
            if (rx == ry) return;
            if (size[rx] < size[ry]) {
                int tmp = rx; rx = ry; ry = tmp;
            }
            parent[ry] = rx;
            size[rx] += size[ry];
        }
    }

    // Kruskal 求连通分量最小生成树
    static int kruskal(List<Integer> nodes, int[] a) {
        int m = nodes.size();
        List<int[]> edges = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                int u = nodes.get(i), v = nodes.get(j);
                int sum = a[u] + a[v];
                if (isPrime[sum]) {
                    edges.add(new int[]{sum, i, j});
                }
            }
        }
        edges.sort(Comparator.comparingInt(e -> e[0]));
        UnionFind uf = new UnionFind(m);
        int total = 0;
        int edgesUsed = 0;
        for (int[] e : edges) {
            if (uf.find(e[1]) != uf.find(e[2])) {
                uf.union(e[1], e[2]);
                total += e[0];
                edgesUsed++;
                if (edgesUsed == m - 1) break;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        int maxAi = 0;
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            if (a[i] > maxAi) maxAi = a[i];
        }
        int limit = Math.max(MAX_VAL, maxAi * 2);
        sieve(limit);

        UnionFind uf = new UnionFind(n);
        // 枚举所有点对合并
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isPrime[a[i] + a[j]]) {
                    uf.union(i, j);
                }
            }
        }

        // 统计连通分量大小
        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = uf.find(i);
            compSize.put(root, uf.size[root]);
        }
        int maxSize = 0;
        for (int sz : compSize.values()) {
            if (sz > maxSize) maxSize = sz;
        }

        int ans = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : compSize.entrySet()) {
            if (entry.getValue() == maxSize) {
                int root = entry.getKey();
                List<Integer> nodes = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (uf.find(i) == root) nodes.add(i);
                }
                int mst = kruskal(nodes, a);
                if (mst < ans) ans = mst;
            }
        }
        System.out.println(ans);
    }
}
